using Repricing.Import;
using Repricing.Execution;
using Repricing.Storage;
namespace Repricing.Tests;
public class StorageTests : IDisposable
{
    readonly string directory=Path.Combine(Path.GetTempPath(),"repricing-"+Guid.NewGuid());
    internal static PriceInput Input(decimal target=75,bool exit=false,decimal? basePrice=null,bool changeBase=false) => new("示例店铺A","MLB","BRL","00123",null,null,null,target,basePrice,exit,changeBase,null);
    internal static ValidationSnapshot Snapshot(int count=2) => new(Guid.NewGuid(),"test.csv",Enumerable.Range(0,count).Select(i=>new ValidatedRow(i+2,"价格",new(),Input() with {Sku=$"SKU-{i}"},[])).ToArray());
    JobStore Store()=>new(directory);
    [Fact] public void AutomaticVerificationBlocksOtherJobsAndLogsOperation(){var s=Store();var job=s.Create(Snapshot(1),ExecutionMode.Simulation);s.TryStart(job.Summary.Id);var row=s.ClaimNext(job.Summary.Id)!;s.RecordVerification(job.Summary.Id,row.Id,new("entered","原价 submit","等待填充"));Assert.Equal(JobStatus.Verifying,s.Get(job.Summary.Id).Summary.Status);Assert.Null(s.ClaimNext(job.Summary.Id));var other=s.Create(Snapshot(1),ExecutionMode.Simulation);Assert.False(s.TryStart(other.Summary.Id));s.RecordVerification(job.Summary.Id,row.Id,new("confirmed","原价 submit","已点击确认"));s.RecordVerification(job.Summary.Id,row.Id,new("passed","原价 submit","已通过，先回读"));Assert.Equal(JobStatus.Running,s.Get(job.Summary.Id).Summary.Status);Assert.Contains(s.Events(job.Summary.Id,0),e=>e.Message.Contains("原价 submit")&&e.Message.Contains("验证自动确认"));}
    [Fact] public void AutomaticVerificationFailureCanBecomeManualPause(){var s=Store();var job=s.Create(Snapshot(1),ExecutionMode.Simulation);s.TryStart(job.Summary.Id);var row=s.ClaimNext(job.Summary.Id)!;s.RecordVerification(job.Summary.Id,row.Id,new("entered","活动 submit","验证跳转"));s.RecordVerification(job.Summary.Id,row.Id,new("failed","活动 submit","连接中断"));s.WaitForVerification(job.Summary.Id,row.Id,"需要验证");Assert.Equal(JobStatus.AwaitingVerification,s.Get(job.Summary.Id).Summary.Status);}
    [Fact] public void OriginalUploadAndStoreNamesSurviveRestart(){var s=Store();var snap=Snapshot(1) with{SourceFile=[0,1,2,255]};snap.Rows[0]=snap.Rows[0] with{Input=snap.Rows[0].Input! with{StoreName="店铺1子账号"}};var job=s.Create(snap,ExecutionMode.Simulation);var loaded=Store();Assert.Equal(snap.SourceFile,loaded.SourceFile(job.Summary.Id));Assert.True(loaded.Get(job.Summary.Id).Summary.HasSourceFile);Assert.Equal(["店铺1子账号"],loaded.List()[0].StoreNames!);}
    [Fact] public void LegacyTaskDoesNotPretendToHaveOriginalFile(){var s=Store();var job=s.Create(Snapshot(1),ExecutionMode.Simulation);Assert.False(job.Summary.HasSourceFile);Assert.Equal(404,Assert.Throws<AppException>(()=>s.SourceFile(job.Summary.Id)).Status);}
    [Fact] public void LogExportContainsMoreThanOnePage(){var s=Store();var job=s.Create(Snapshot(1),ExecutionMode.Simulation);for(var i=0;i<510;i++)s.AddEvent(job.Summary.Id,$"日志-{i}");Assert.Equal(500,s.Events(job.Summary.Id,0).Length);var text=System.Text.Encoding.UTF8.GetString(s.ExportLog(job.Summary.Id));Assert.Contains("日志-0",text);Assert.Contains("日志-509",text);Assert.Contains("示例店铺A",text);}
    [Fact] public void PersistsRowsAndEvents(){var s=Store();var job=s.Create(Snapshot(),ExecutionMode.Simulation);s.AddEvent(job.Summary.Id,"test");var reloaded=Store();Assert.Equal(2,reloaded.Get(job.Summary.Id).Rows.Length);Assert.Contains(reloaded.Events(job.Summary.Id,0),e=>e.Message=="test");}
    [Fact] public void InvalidRowsCannotExecute(){var snap=Snapshot();snap.Rows[0]=snap.Rows[0] with {Input=null,Errors=["无效价格"]};var j=Store().Create(snap,ExecutionMode.Simulation);Assert.Equal(RowStatus.Invalid,j.Rows[0].Status);}
    [Fact] public void DuplicateCreateReturnsSameJob(){var s=Store();var v=Snapshot();Assert.Equal(s.Create(v,ExecutionMode.Simulation).Summary.Id,s.Create(v,ExecutionMode.Simulation).Summary.Id);}
    [Fact] public void CreateJobRejectsStaleValidation(){var sessions=new ImportSessionStore(new());var id=sessions.Add("test.csv",[new("价格",["店铺","站点","SKU","目标售价"],[new(2,new(){["店铺"]=new("A",false,false),["站点"]=new("BR",false,false),["SKU"]=new("X",false,false),["目标售价"]=new("75",false,false)})])]);var map=new PriceValidator().SuggestMapping(["店铺","站点","SKU","目标售价"]);var old=sessions.Validate(id,new("价格",map,null));sessions.Validate(id,new("价格",map,null));Assert.Throws<AppException>(()=>sessions.GetValidation(old.ValidationId));}
    [Fact] public void MixedConsentCannotUpgradeExistingLegacyJob(){var s=Store();var snap=Snapshot(1);var job=s.Create(snap,ExecutionMode.PriceCut);Assert.False(job.Summary.MixedPrices);Assert.Throws<AppException>(()=>s.Create(snap,ExecutionMode.PriceCut,true));Assert.False(Store().Get(job.Summary.Id).Summary.MixedPrices);}
    (JobStore Store,JobDetail Job,JobRow Row,PriceCutPlan Plan) Increase(bool consent=true){var s=Store();var snap=Snapshot(1);snap.Rows[0]=snap.Rows[0] with{Input=snap.Rows[0].Input! with{TargetPrice=90,Action="提价"}};var job=s.Create(snap,ExecutionMode.PriceCut,consent);s.TryStart(job.Summary.Id);var row=s.ClaimNext(job.Summary.Id)!;var p=new ZiniaoProduct("456",row.Source.Input!.Sku,"商品","R$ 100",[new("C-1","活动","激活","R$ 80",true,true)]);return(s,job,row,new(new(row.Source.Input.Store,"测试","MercadoLibre-巴西"),row.Source.Input,p,"C-1",80,100,Rejoin:true,Stage:"exit"));}
    [Fact] public void ExitAndJoinAreDurableOrderedCheckpoints(){var(s,j,r,p)=Increase();s.SavePriceCutPlan(j.Summary.Id,r.Id,p);Assert.Equal("exit",Store().Get(j.Summary.Id).Rows[0].PriceCut!.Stage);Assert.Throws<AppException>(()=>s.SavePriceCutPlan(j.Summary.Id,r.Id,p));var join=p with{Stage="join",OfferPrice=95};s.SavePriceCutPlan(j.Summary.Id,r.Id,join);Assert.Equal("join",Store().Get(j.Summary.Id).Rows[0].PriceCut!.Stage);Assert.Throws<AppException>(()=>s.SavePriceCutPlan(j.Summary.Id,r.Id,join));Assert.Throws<AppException>(()=>s.SavePriceCutPlan(j.Summary.Id,r.Id,p));}
    [Fact] public void RetryCannotCheckpointAnotherExit(){var(s,j,r,p)=Increase();s.SavePriceCutPlan(j.Summary.Id,r.Id,p);s.UpdateRow(j.Summary.Id,r.Id,new(RowStatus.NeedsReview,"提价","退出结果未知","increase-review",Retryable:true));var retry=s.ClaimNext(j.Summary.Id)!;Assert.Equal(2,retry.Attempts);Assert.Throws<AppException>(()=>s.SavePriceCutPlan(j.Summary.Id,r.Id,p));}
    [Fact] public void FirstCheckpointCannotChangeRowTarget(){var(s,j,r,p)=Increase();Assert.Throws<AppException>(()=>s.SavePriceCutPlan(j.Summary.Id,r.Id,p with{Input=p.Input with{TargetPrice=91}}));}
    [Fact] public void LegacyJobCannotPersistExitPlan(){var(s,j,r,p)=Increase(false);Assert.Throws<AppException>(()=>s.SavePriceCutPlan(j.Summary.Id,r.Id,p));}
    [Fact] public void SubsidyConsentCannotUpgradeExistingJob(){var s=Store();var snap=Snapshot(1);var job=s.Create(snap,ExecutionMode.PriceCut,true,true);Assert.Throws<AppException>(()=>s.Create(snap,ExecutionMode.PriceCut,true,true,true));Assert.False(s.Get(job.Summary.Id).Summary.SubsidyExits);}
    [Fact] public void PlanCannotAddUnconfirmedSubsidyPermission(){var(s,j,r,p)=Increase();Assert.Throws<AppException>(()=>s.SavePriceCutPlan(j.Summary.Id,r.Id,p with{Input=p.Input with{AllowExit=true}}));}
    [Theory] [InlineData(false)] [InlineData(true)] public void SplitAcceptsOnlyConfirmedEffectivePermission(bool consent)
    {
        var s=Store();var j=s.Create(Snapshot(1),ExecutionMode.PriceCut,true,true,consent);s.TryStart(j.Summary.Id);var row=s.ClaimNext(j.Summary.Id)!;var input=row.Source.Input!;
        var split=new[]{input with{ItemId="456",AllowExit=true},input with{ItemId="789",AllowExit=true}};
        if(!consent){Assert.Throws<AppException>(()=>s.SplitPriceCutRow(j.Summary.Id,row.Id,split));return;}
        Assert.Throws<AppException>(()=>s.SplitPriceCutRow(j.Summary.Id,row.Id,[split[0],split[1] with{TargetPrice=99}]));
        s.SplitPriceCutRow(j.Summary.Id,row.Id,split);var children=s.Get(j.Summary.Id).Rows;Assert.Equal(2,children.Length);Assert.All(children,r=>Assert.Equal(input,r.Source.Input! with{ItemId=null}));Assert.True(s.Get(j.Summary.Id).Summary.SubsidyExits);
    }
    [Fact] public void SellerDiscountReplacementHasDurableExitAndJoinBinding()
    {
        var(s,j,r,p)=Increase();p=p with{PromotionId="D-PRICE-DISCOUNT",RejoinPromotionId="C-1",Product=p.Product with{Promotions=[new("D-PRICE-DISCOUNT","百分比折扣\n16/10月至8/11月","激活","R$ 80",true,true),new("C-1","普通活动","","R$ 95",false,false,false,true)]}};
        s.SavePriceCutPlan(j.Summary.Id,r.Id,p);s.SavePriceCutPlan(j.Summary.Id,r.Id,p with{Stage="join",OfferPrice=95});Assert.Equal("C-1",s.Get(j.Summary.Id).Rows[0].PriceCut!.RejoinPromotionId);
        Assert.Throws<AppException>(()=>s.SavePriceCutPlan(j.Summary.Id,r.Id,p with{Stage="join",OfferPrice=95,RejoinPromotionId="C-2"}));
    }
    [Fact] public void CannotStartAtJoinOrChangeTargetBetweenStages(){var(s,j,r,p)=Increase();Assert.Throws<AppException>(()=>s.SavePriceCutPlan(j.Summary.Id,r.Id,p with{Stage="join",OfferPrice=95}));s.SavePriceCutPlan(j.Summary.Id,r.Id,p);Assert.Throws<AppException>(()=>s.SavePriceCutPlan(j.Summary.Id,r.Id,p with{Stage="join",OfferPrice=95,Input=p.Input with{TargetPrice=91}}));}
    [Fact] public void BaseConsentDoesNotUpgradeOldMixedJobs(){var s=Store();var snap=Snapshot(1);var job=s.Create(snap,ExecutionMode.PriceCut,true);Assert.False(job.Summary.BasePrices);Assert.Throws<AppException>(()=>s.Create(snap,ExecutionMode.PriceCut,true,true));Assert.False(Store().Get(job.Summary.Id).Summary.BasePrices);}
    [Theory] [InlineData(false)] [InlineData(true)] public void BaseStagesNeedConsentAndNeverRepeatExit(bool consent)
    {
        var s=Store();var snap=Snapshot(1);snap.Rows[0]=snap.Rows[0] with{Input=snap.Rows[0].Input! with{TargetPrice=99}};var job=s.Create(snap,ExecutionMode.PriceCut,true,consent);s.TryStart(job.Summary.Id);var row=s.ClaimNext(job.Summary.Id)!;
        var p=new ZiniaoProduct("456",row.Source.Input!.Sku,"商品","R$ 100",[new("P-1","补贴","激活","R$ 80",true,true)]);var plan=new PriceCutPlan(new(row.Source.Input.Store,"测试","MercadoLibre-巴西"),row.Source.Input,p,"P-1",80,100,Stage:"base-exit",ChangeBase:true);
        if(!consent){Assert.Throws<AppException>(()=>s.SavePriceCutPlan(job.Summary.Id,row.Id,plan));return;}
        s.SavePriceCutPlan(job.Summary.Id,row.Id,plan);var save=plan with{Stage="base-save"};s.SavePriceCutPlan(job.Summary.Id,row.Id,save);Assert.Throws<AppException>(()=>s.SavePriceCutPlan(job.Summary.Id,row.Id,save));
        s.UpdateRow(job.Summary.Id,row.Id,new(RowStatus.NeedsReview,"改原价","保存未知","base-review",Retryable:true));s.ClaimNext(job.Summary.Id);Assert.Throws<AppException>(()=>s.SavePriceCutPlan(job.Summary.Id,row.Id,plan));s.SavePriceCutPlan(job.Summary.Id,row.Id,save);Assert.Equal("base-save",Store().Get(job.Summary.Id).Rows[0].PriceCut!.Stage);
    }
    [Fact] public void IncomePolicyPersistsAndCannotUpgradeAnExistingBatch(){var store=Store();var snap=Snapshot(1);var old=store.Create(snap,ExecutionMode.PriceCut,true,true,true);Assert.False(old.Summary.IncomePriority);Assert.Throws<AppException>(()=>store.Create(snap,ExecutionMode.PriceCut,true,true,true,true));var current=store.Create(Snapshot(1),ExecutionMode.PriceCut,true,true,true,true);Assert.True(Store().Get(current.Summary.Id).Summary.IncomePriority);}
    public void Dispose(){Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(Directory.Exists(directory))Directory.Delete(directory,true);}
}
